mapper.select:
SELECT c.ID AS id, c.FLOW_DEFINITION_ID AS flowDefinitionId, c.NODE_ID AS nodeId, c.NODE_TYPE AS nodeType, c.CONFIG_JSON AS configJson, c.ENV_CODE AS envCode, c.DELETED AS deleted, c.CREATE_USER AS createUser, c.CREATE_TIME AS createTime, c.UPDATE_USER AS updateUser, c.UPDATE_TIME AS updateTime FROM AST_FLOW_NODE_CONFIG c WHERE (c.DELETED = 0 OR c.DELETED IS NULL)
AND c.FLOW_DEFINITION_ID = #{req.flowDefinitionId}
AND c.NODE_ID LIKE CONCAT('%', #{req.nodeId}, '%')
AND c.NODE_TYPE = #{req.nodeType}
AND c.ENV_CODE = #{req.envCode}
ORDER BY c.UPDATE_TIME DESC, c.ID DESC
